<?php
declare(strict_types=1);
function dutySelect(string $key,string $label,array $options,mixed $value=''):string {$s='<label class="field">'.h($label).'<select name="'.h($key).'">';foreach($options as $k=>$name)$s.='<option value="'.h($k).'"'.((string)$k===(string)$value?' selected':'').'>'.h($name).'</option>';return $s.'</select></label>';}
function ownDutiesView(array $u):string {$items=ownDuties((int)$u['id']);if(!$items)return '';$html='<section class="panel" id="my-duties"><h2>あなたの担当</h2><div class="grid-2">';foreach($items as $x)$html.='<article class="panel"><h3>'.h($x['label']).'</h3><p>'.h(DUTY_STATUS[$x['status']]).' ／ '.h($x['scope']).'</p><p>'.h($x['description']).'</p>'.($x['dueDate']?'<p>対応予定日：'.h($x['dueDate']).'</p>':'').'</article>';return $html.'</div>'.(in_array($u['role'],['owner','organizer'],true)?'<a class="btn btn-outline" href="?page=admin_contacts&amp;mine=yes">自分の担当を一覧で確認</a>':'').'</section>';}
function dutyFormView(array $x=[]):string {
 $users=[''=>'登録者を選択'];foreach(all('SELECT id,name FROM users ORDER BY id') as $p)$users[$p['id']]=$p['name'].'（ID '.$p['id'].'）';$classes=[0=>'全体・クラス指定なし'];for($i=1;$i<=10;$i++)$classes[$i]='3年'.$i.'組';
 return '<section class="panel" id="duty-editor"><h2>'.(!empty($x['id'])?'担当を編集する':'担当を登録する').'</h2><p>1人に複数の担当を登録できます。担当名だけでは管理権限は増えず、外部協力者にログイン権限は付きません。</p>'.form('duty_save',hidden('id',$x['id']??0).hidden('revision',$x['revision']??0).'<div class="grid-2">'.dutySelect('roleKey','担当',[''=>'担当を選択']+DUTY_ROLES,$x['roleKey']??'').input('customRole','その他の担当名',$x['customRole']??'','text',false).dutySelect('kind','担当者の区分',['member'=>'登録者から選ぶ','external'=>'外部協力者'],$x['kind']??'member').dutySelect('userId','登録者（外部協力者の場合は不要）',$users,$x['userId']??'').input('externalName','外部協力者の氏名',$x['externalName']??'','text',false).input('contact','外部協力者の連絡メモ（幹事のみ）',$x['contact']??'','text',false).dutySelect('class','対象クラス',$classes,$x['class']??0).dutySelect('status','担当状況',DUTY_STATUS,$x['status']??'active').input('scope','担当範囲・係名',$x['scope']??'','text',false).input('dueDate','対応予定日（任意）',$x['dueDate']??'','date',false).'</div><label class="field">担当内容（本人にも表示）<textarea name="description" maxlength="2000" rows="3">'.h($x['description']??'').'</textarea></label><label class="field">幹事内メモ（本人向け画面には非表示）<textarea name="note" maxlength="2000" rows="3">'.h($x['note']??'').'</textarea></label>'.reasons().'<p class="mini-note">解除する場合は担当状況を「担当解除」にして保存します。変更履歴は残ります。</p>'.button('担当を保存する')).'</section>';
}
function dutiesView(array $u):string {
 adminInquiry($u);$owner=$u['role']==='owner';$f=$_GET;$all=dutyRows($u);$items=filterDuties($all,$f,(int)$u['id']);if(($f['mode']??'')==='classes'){requirev($owner,'クラス幹事の設定は管理者が行います。');return '<p><a href="?page=admin_contacts">← 担当一覧へ</a></p>'.str_replace('?page=admin_contacts&amp;class=','?page=admin_contacts&amp;mode=classes&amp;class=',contactsAdminView());}
 $classes=[''=>'すべて'];for($i=1;$i<=10;$i++)$classes[$i]='3年'.$i.'組';$html='<h1>担当管理</h1><p>同窓会を支える担当をまとめて確認できます。担当名とシステムの管理権限は別です。</p>'.grid([['担当登録件数',count($all).'件'],['自分の担当数',count(ownDuties((int)$u['id'])).'件'],['外部協力件数',count(array_filter($all,fn($x)=>$x['kind']==='external'&&$x['status']!=='inactive')).'件']]);
 $html.='<section class="panel"><h2>担当を探す</h2><div class="button-row"><a class="btn btn-outline" href="?page=admin_contacts#duty-results">すべて</a><a class="btn btn-outline" href="?page=admin_contacts&amp;mine=yes#duty-results">自分の担当</a><a class="btn btn-outline" href="?page=admin_contacts&amp;kind=external#duty-results">外部協力者</a><a class="btn btn-outline" href="?page=admin_contacts&amp;role=class#duty-results">クラス幹事</a></div><form method="get" action="?page=admin_contacts#duty-results">'.hidden('page','admin_contacts').'<div class="grid-2">'.input('q','氏名・担当内容で検索',$f['q']??'','search',false).dutySelect('role','担当',[''=>'すべて','class'=>'クラス幹事']+DUTY_ROLES,$f['role']??'').dutySelect('class','クラス（対象または所属）',$classes,$f['class']??'').dutySelect('kind','区分',[''=>'すべて','member'=>'登録者','external'=>'外部協力者'],$f['kind']??'').dutySelect('status','担当状況',[''=>'すべて']+DUTY_STATUS,$f['status']??'').dutySelect('mine','表示対象',[''=>'全担当','yes'=>'自分の担当'],$f['mine']??'').'</div>'.button('絞り込む').'</form></section>';
 $params=array_intersect_key($f,array_flip(['q','role','class','kind','status','mine']));$html.='<div class="button-row">'.($owner?'<a class="btn" href="?page=admin_contacts&amp;new=yes#duty-editor">担当を追加</a><a class="btn btn-outline" href="?page=admin_contacts&amp;mode=classes">クラス幹事の設定</a>':'<p>設定・編集は管理者が行います。</p>').'<a class="btn btn-outline" href="?'.h(http_build_query(['page'=>'export','kind'=>'duties','dutyKind'=>$params['kind']??'',...array_diff_key($params,['kind'=>1])])).'">表示中の一覧CSV</a></div><p id="duty-results" tabindex="-1">'.count($items).'件を表示 ／ 氏名を押すと担当の詳細を確認できます。</p>';
 $rows=[];foreach($items as $x)$rows[]=[h($x['label']).'<br>'.h(DUTY_STATUS[$x['status']]),'<a href="?page=admin_contacts&amp;'.($x['source']==='class'?'person='.$x['userId']:'detail='.$x['id']).'">'.h($x['name']).'</a><br>'.h($x['kind']==='external'?'外部協力者':registrationClassLabel($x['personClass'])),h($x['class']?'3年'.$x['class'].'組':'全体').'<br>'.h($x['scope']).'<br>'.h($x['description']),h($x['dueDate']?:'—'),$owner?'<a class="btn btn-outline" href="?page=admin_contacts&amp;'.($x['source']==='class'?'mode=classes&amp;class='.$x['class']:'edit='.$x['id']).'#duty-editor">編集</a>':'閲覧のみ'];$html.=tabler(['担当・状況','担当者','対象・担当内容','予定日','操作'],$rows);
 if(!empty($f['detail'])||!empty($f['person'])){$html.='<section class="panel" id="duty-detail"><h2>担当の詳細</h2>';foreach($all as $x)if(!empty($f['person'])?$x['userId']===(int)$f['person']:$x['source']==='duty'&&$x['id']===(int)$f['detail'])$html.='<article><h3>'.h($x['name']).' ／ '.h($x['label']).'</h3><p>'.h($x['description']).'</p><p>担当範囲：'.h($x['scope']?:'—').' ／ '.h(DUTY_STATUS[$x['status']]).'</p>'.($x['source']==='duty'?'<p>連絡メモ：'.h($x['contact']?:'—').'</p><p>幹事内メモ：'.h($x['note']?:'—').'</p><p>更新日時：'.h($x['updated']).'</p>':'').'</article>';$html.='</section>';}
 if($owner&&(!empty($f['new'])||!empty($f['edit']))){$record=!empty($f['edit'])?one('SELECT * FROM duties WHERE id=?',[(int)$f['edit']]):null;$html.=$record?dutyFormView([...obj($record['data_json']),'id'=>(int)$record['id'],'revision'=>(int)$record['revision']]):(!empty($f['new'])?dutyFormView():'<p>担当記録がありません。</p>');}return $html;
}
